export {
  collaborationSpaceKindSchema,
  directoryWorkspaceRef,
  gitWorkspaceRef,
  normalizeWorkspaceRoot,
  resolveCollaborationSpace,
  workspaceRefSchema,
  workspaceKeyForRoot,
} from "./space.ts";
export type { CollaborationSpaceKind, WorkspaceRef } from "./space.ts";
export {
  assertActiveWorkContextBinding,
  bindingIdForSession,
  bindWorkContext,
  requireWorkContextBinding,
  readStoredWorkContextBinding,
  resolveWorkContextStateRoot,
  supersedeWorkContextBinding,
  workContextBindingViewSchema,
  workContextBindingView,
  WorkContextError,
} from "./binding.ts";
export type {
  BindWorkContextOptions,
  RequireWorkContextBindingOptions,
  SupersedeWorkContextBindingOptions,
  WorkContextBinding,
  WorkContextBindingView,
  WorkContextErrorCode,
} from "./binding.ts";
export * from "./doctor.ts";
export * from "./rejections.ts";
export {
  bindCodexWorkContext,
  refreshCodexWorkContext,
  renderWorkContext,
  renderWorkContextDiagnostic,
  requireCodexWorkContext,
  writeWorkContextDiagnostic,
} from "./codex.ts";
export type { BindCodexWorkContextOptions, CodexSessionStartSource } from "./codex.ts";

export const workContextBindingViewSchema = z
  .object({
    version: z.literal(1),
    id: z.string().regex(/^wctx_[a-f0-9]{32}$/),
    status: z.enum(["active", "superseded"]),
    host: z.string().min(1),
    bound_at: z.iso.datetime(),
    last_seen_at: z.iso.datetime(),
    expires_at: z.iso.datetime(),
    collaboration_space: workspaceRefSchema,
    provenance: z
      .object({
        kind: z.enum(["host_lifecycle", "operator_rebind"]),
        lifecycle: z.string().min(1),
      })
      .strict(),
    superseded_by: z.string().regex(/^wctx_[a-f0-9]{32}$/).optional(),
    superseded_at: z.iso.datetime().optional(),
  })
  .strict();
export type WorkContextBindingView = z.infer<typeof workContextBindingViewSchema>;

type Clock = () => string;

import { spawn } from "node:child_process";
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { constants as fsConstants } from "node:fs";
import {
  chmod,
  mkdir,
  open,
  readdir,
  readFile,
  rename,
  rm,
  stat,
} from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { join } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";
import * as z from "zod/v4";

import {
  assertActiveWorkContextBinding,
  resolveWorkContextStateRoot,
} from "../work-context/index.ts";
import type { WorkContextBinding } from "../work-context/index.ts";
import {
  TOOL_RESULT_MAX_INLINE_BYTES,
  TOOL_RESULT_MAX_SLICE_BYTES,
  ToolResultError,
  toolResultHealthOutputSchema,
  toolResultManifestOutputSchema,
  toolResultReceiptSchema,
  toolResultSearchOutputSchema,
  toolResultSliceOutputSchema,
} from "./schemas.ts";
import type {
  ToolResultHealthOutput,
  ToolResultManifestOutput,
  ToolResultReceipt,
  ToolResultSearchOutput,
  ToolResultSliceOutput,
} from "./schemas.ts";

const MAX_ARTEFACT_BYTES = 64 * 1024 * 1024;
const MAX_STORE_BYTES = 512 * 1024 * 1024;
const RETENTION_MS = 24 * 60 * 60 * 1_000;
const MAX_SEARCH_MATCHES = 100;
const MAX_QUERY_BYTES = 1024;
const STORE_LOCK_TIMEOUT_MS = 5_000;
const STORE_LOCK_STALE_MS = 30_000;
const LOCK_RETRY_MS = 20;

type Clock = () => string;

type CaptureCommandResultOptions = {
  argv: string[];
  producer: string;
  binding: WorkContextBinding;
  stateRoot?: string;
  cwd?: string;
  now?: Clock;
};

type BoundResultOptions = {
  binding: WorkContextBinding;
  resultId: string;

function isWorkContextBinding(value: unknown): value is WorkContextBinding {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<WorkContextBinding>;
  const provenance = candidate.provenance;
  return (
    candidate.version === 1 &&
    typeof candidate.id === "string" &&
    (candidate.status === "active" || candidate.status === "superseded") &&
    typeof candidate.host === "string" &&
    typeof candidate.session_id === "string" &&
    typeof candidate.bound_at === "string" &&
    typeof candidate.last_seen_at === "string" &&
    typeof candidate.expires_at === "string" &&
    isWorkspaceRef(candidate.collaboration_space) &&
    typeof provenance === "object" &&
    provenance !== null &&
    (provenance.kind === "host_lifecycle" || provenance.kind === "operator_rebind") &&
    typeof provenance.lifecycle === "string" &&
    typeof provenance.observed_cwd === "string" &&
    (candidate.superseded_by === undefined || typeof candidate.superseded_by === "string") &&
    (candidate.superseded_at === undefined || typeof candidate.superseded_at === "string")
  );
}

